    g=[r[:] for r in grid]
    R=len(g); C=len(g[0])
    for c in range(C):
        if g[R-1][c] != 5: continue
        color=5
        for r in range(R-1,-1,-1):
            if g[r][c]==0: g[r][c]=color
            else: color=g[r][c]
    return g
